const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const dateStr = '2018-10-22';
    const start = ee.Date(dateStr);
    const end = start.advance(1, 'day');

    // Upper Arrow Lake approximate bounding polygon (BC, Canada)
    const region = ee.Geometry.Polygon(
      [[[-118.55, 51.20], [-117.45, 51.20], [-117.45, 49.80], [-118.55, 49.80], [-118.55, 51.20]]],
      null, false
    );

    // Valley mask: low elevation + gentle slope (approximate valley floor)
    const srtm = ee.Image('USGS/SRTMGL1_003');
    const slope = ee.Terrain.slope(srtm);
    const valleyMask = srtm.lt(800).and(slope.lt(8)); // elevation <800 m and slope <8 deg

    // 2. Data Acquisition & Check
    const terraCol = ee.ImageCollection('MODIS/061/MOD09GA')
      .filterDate(start, end)
      .filterBounds(region);
    const aquaCol = ee.ImageCollection('MODIS/061/MYD09GA')
      .filterDate(start, end)
      .filterBounds(region);

    const [terraSize, aquaSize] = await Promise.all([
      new Promise((res, rej) => terraCol.size().getInfo((v, e) => e ? rej(e) : res(v))),
      new Promise((res, rej) => aquaCol.size().getInfo((v, e) => e ? rej(e) : res(v))),
    ]);

    console.log(`Terra images: ${terraSize}, Aqua images: ${aquaSize}`);
    if (terraSize === 0 || aquaSize === 0) {
      console.log('Empty image collection for one or both sensors on the date.');
      console.log('C1');
      return;
    }

    // 3. Processing helpers
    function cloudFromState(state) {
      // Bits 0-1: 00 clear, 01 cloudy, 10 mixed, 11 not set
      const bits01 = state.bitwiseAnd(3);
      return bits01.eq(1).or(bits01.eq(2)).rename('cloudy'); // cloudy or mixed
    }

    async function cloudStats(col, label) {
      const img = col.mosaic().clip(region);
      const state = img.select('state_1km');
      const cloudy = cloudFromState(state);

      const validCount = await new Promise((res, rej) =>
        state.updateMask(valleyMask)
          .reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: region,
            scale: 1000,
            maxPixels: 1e9,
          })
          .get('state_1km')
          .getInfo((v, e) => e ? rej(e) : res(v))
      );

      if (validCount === null || validCount === 0) {
        return { label, valid: 0, cloudy: 0, pct: null };
      }

      const cloudyCount = await new Promise((res, rej) =>
        cloudy.updateMask(valleyMask)
          .reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: region,
            scale: 1000,
            maxPixels: 1e9,
          })
          .get('cloudy')
          .getInfo((v, e) => e ? rej(e) : res(v))
      );

      const cc = cloudyCount || 0;
      const pct = (cc / validCount) * 100.0;
      return { label, valid: validCount, cloudy: cc, pct };
    }

    // 4. Calculation
    const [morning, afternoon] = await Promise.all([
      cloudStats(terraCol, 'Morning (Terra)'),
      cloudStats(aquaCol, 'Afternoon (Aqua)'),
    ]);

    // 5. Validation & Final Answer
    if (morning.valid === 0 || afternoon.valid === 0) {
      console.log('No valid pixels after masking valley area and data availability.');
      console.log('C2');
      return;
    }
    if (
      morning.pct === null || afternoon.pct === null ||
      !isFinite(morning.pct) || !isFinite(afternoon.pct) ||
      morning.pct < 0 || afternoon.pct < 0 || morning.pct > 100 || afternoon.pct > 100
    ) {
      console.log('Invalid calculation (NaN/None/out-of-range).');
      console.log('C3');
      return;
    }

    console.log(`${morning.label}: Valid=${morning.valid}, Cloud=${morning.cloudy}, Cloud%= ${morning.pct.toFixed(1)}`);
    console.log(`${afternoon.label}: Valid=${afternoon.valid}, Cloud=${afternoon.cloudy}, Cloud%= ${afternoon.pct.toFixed(1)}`);

    const diff = morning.pct - afternoon.pct;
    console.log(`Change (Morning - Afternoon) Cloud%: ${diff.toFixed(1)}`);

    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
